def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    ones = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 1]
    sixes = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 6]

    for i, (r1, c1) in enumerate(ones):
        for r2, c2 in ones[i + 1:]:
            if r1 == r2 or abs(r2 - r1) != abs(c2 - c1):
                continue

            dr = 1 if r2 > r1 else -1
            dc = 1 if c2 > c1 else -1

            # Draw the 1-colored segment between the two markers.
            r, c = r1, c1
            while True:
                out[r][c] = 1
                if (r, c) == (r2, c2):
                    break
                r += dr
                c += dc

            # A 6 lying on this segment produces a full perpendicular diagonal.
            for sr, sc in sixes:
                if (sr - r1) * (c2 - c1) == (sc - c1) * (r2 - r1):
                    if min(r1, r2) <= sr <= max(r1, r2) and min(c1, c2) <= sc <= max(c1, c2):
                        pr, pc = 1, -dr * dc
                        rr, cc = sr, sc
                        while 0 <= rr - pr < h and 0 <= cc - pc < w:
                            rr -= pr
                            cc -= pc
                        while 0 <= rr < h and 0 <= cc < w:
                            out[rr][cc] = 6
                            rr += pr
                            cc += pc
    return out
